/* Phase 2 additions: games room, social, video portal, automation/email, AI copilot, attendance anomalies,
   payroll prep, positions & JD register, BI exports */
const ens = (k, v) => (DB[k] === undefined ? (DB[k] = v) : DB[k]);
const first = n => n.split(' ')[0];
const hm = s => { const [h,m] = s.split(':').map(Number); return h*60+m; };
const fmtHM = m => `${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`;
const rnd = n => { const a = new Uint32Array(1); crypto.getRandomValues(a); return a[0] % n; };

/* ================= GAMES ROOM (HR-051) ================= */
const QUIZZES = [
 {id:'q1',title:'Health & Safety basics',qs:[
  ['What does COSHH stand for?',['Control of Substances Hazardous to Health','Care of Staff Handling Hazards','Control of Safe Handling Hours'],0],
  ['What is the UK legal maximum temperature for most chilled food?',['5°C','8°C','12°C'],1],
  ['When lifting a load you should…',['Keep it close to your body','Twist while lifting','Lock your legs and bend your back'],0],
  ['After a near miss you should…',['Ignore it','Report it immediately','Wait for the monthly meeting'],1],
  ['Fire exits must be…',['Locked at night','Kept clear at all times','Used for storage'],1]]},
 {id:'q2',title:'HR portal know-how',qs:[
  ['Where do you request annual leave?',['The HR portal','WhatsApp','By phone only'],0],
  ['Who approves your annual leave request?',['Your line manager','Reception','Nobody'],0],
  ['A return-to-work interview happens…',['After a sickness absence','Only after holidays','Never'],0],
  ['On the leave calendar, HOL is shown in…',['Blue','Red','Pink'],0],
  ['How far ahead can you plan holidays in the portal?',['Up to two years','One week','Not at all'],0]]}
];
const WORDS = ['WAREHOUSE','LOGISTICS','COMPLIANCE','HOLIDAY','TEAMWORK','DELIVERY','SAFETY','FRESHWAYS','CUSTOMER','PAYROLL'];
const G = () => ens('games', {pts:{}, done:{}, words:{}, raffles:[], memory:{}, extra:[]});
const addPts = (uid_, n) => { G().pts[uid_] = (G().pts[uid_]||0) + n; };
function allQuizzes(){ return QUIZZES.concat(G().extra||[]); }
VIEWS.games = () => {
  const g = G(), u = me(), today = D.todayIso(), board = Object.entries(g.pts).filter(([id])=>emp(id)).sort((a,b)=>b[1]-a[1]).slice(0,8);
  const doy = Math.floor(D.diff(today.slice(0,4)+'-01-01', today)), word = WORDS[doy % WORDS.length], doneW = g.words[u.id+'|'+today];
  return pageHead('Games Room','Quizzes, puzzles and raffles – a bit of fun, with points on the leaderboard.', isHR()?`<button class="btn" data-act="newQuiz">${ico('plus')} New quiz</button><button class="btn pri" data-act="newRaffle">${ico('plus')} New raffle</button>`:'') +
  `<div class="grid g-main"><div class="grid">
   <div class="card"><h3><span class="l">${ico('help')} Quizzes</span></h3><div class="grid g2">${allQuizzes().map(q=>{ const d = g.done[u.id+'|'+q.id]; return `<div class="card flat game-card"><b>${esc(q.title)}</b><span class="small muted">${q.qs.length} questions · 2 points per correct answer, +5 for full marks</span>${d!==undefined?badge('Your score '+d+'/'+q.qs.length,'ok'):''}<div class="row"><button class="btn sm pri" data-act="playQuiz" data-id="${q.id}">${d!==undefined?'Review / retake for fun':'Play'}</button></div></div>`; }).join('')}</div></div>
   <div class="grid g2">
    <div class="card game-card"><h3><span class="l">${ico('smile')} Word scramble</span>${doneW?badge('Solved today','ok'):''}</h3><div class="scr">${scramble(word, doy)}</div><div class="row"><input id="wsi" placeholder="Your answer" maxlength="20" style="text-transform:uppercase"><button class="btn pri" data-act="wordCheck" data-w="${word}">Check</button></div><span class="small muted">A new word every day · +5 points</span></div>
    <div class="card game-card"><h3><span class="l">${ico('grid')} Memory match</span></h3><p class="muted small" style="margin:0">Find all six pairs in as few moves as you can. 14 moves or fewer earns 10 points, otherwise 5 (once a day).</p><button class="btn pri" data-act="memStart">Play</button></div>
   </div>
   ${brainCards()}
   <div class="card"><h3><span class="l">${ico('star')} Raffles</span></h3>${g.raffles.map(r=>`<div class="li"><div class="grow"><b>${esc(r.title)}</b> ${badge(r.winner?'Drawn':'Open',r.winner?'':'ok')}<div class="small muted">Prize: ${esc(r.prize)} · closes ${fmt(r.closes)} · ${r.entrants.length} entr${r.entrants.length===1?'y':'ies'}${r.winner?` · Winner: <b>${esc(empName(r.winner))}</b>`:''}</div></div>${!r.winner&&!r.entrants.includes(u.id)&&r.closes>=today?`<button class="btn sm pri" data-act="raffleIn" data-id="${r.id}">Enter</button>`:r.entrants.includes(u.id)&&!r.winner?badge('Entered','info'):''}${isHR()&&!r.winner&&r.entrants.length?`<button class="btn sm" data-act="raffleDraw" data-id="${r.id}">Draw winner</button>`:''}</div>`).join('')||'<div class="empty">No raffles right now.</div>'}<p class="small muted" style="margin:10px 0 0">Draws use a secure random number and are recorded in the activity log. Prizes must be approved by HR/Finance.</p></div>
  </div>
  <div class="card" style="align-self:start"><h3><span class="l">${ico('award')} Leaderboard</span></h3>${board.map(([id,p],i)=>`<div class="li"><b style="width:22px">${i+1}</b>${av(id,30)}<span class="grow">${esc(empName(id))}</span><b>${p}</b></div>`).join('')||'<div class="empty">Play a game to get on the board.</div>'}<p class="small muted" style="margin:10px 0 0">Your points: <b>${g.pts[u.id]||0}</b></p></div></div>`;
};
function scramble(w, seed){ const a = w.split(''); let s = seed*7919+13; for(let i=a.length-1;i>0;i--){ s = (s*1103515245+12345)&0x7fffffff; const j = s%(i+1); [a[i],a[j]] = [a[j],a[i]]; } const r = a.join(''); return r===w ? a.reverse().join('') : r; }
ACT.wordCheck = el => { const g = G(), k = SESSION.uid+'|'+D.todayIso(); const v = $('#wsi').value.trim().toUpperCase(); if(!v) return; if(v!==el.dataset.w) return toast('Not quite – try again!','bad'); if(g.words[k]) return toast('Already solved today.'); g.words[k] = 1; addPts(SESSION.uid,5); log('Game','Word scramble solved'); saveDB(); toast('Correct! +5 points','ok'); render(); };
ACT.playQuiz = el => { const q = allQuizzes().find(x=>x.id===el.dataset.id); modal({title:esc(q.title),size:'wide',body:`<form id="qf">${q.qs.map((x,i)=>`<div class="field"><label>${i+1}. ${esc(x[0])}</label>${x[1].map((o,k)=>`<label class="row" style="font-weight:500;margin:4px 0;gap:8px"><input type="radio" name="q${i}" value="${k}" style="width:auto"> ${esc(o)}</label>`).join('')}</div>`).join('')}</form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Submit answers',cls:'pri',act:'quizSubmit',data:`data-id="${q.id}"`}]}); };
ACT.quizSubmit = el => { const q = allQuizzes().find(x=>x.id===el.dataset.id), f = $('#qf'); let sc = 0, miss = 0; q.qs.forEach((x,i)=>{ const v = f.querySelector(`input[name=q${i}]:checked`); if(!v) miss++; else if(+v.value===x[2]) sc++; }); if(miss) return toast('Please answer every question.','bad');
  const k = SESSION.uid+'|'+q.id, first_ = G().done[k]===undefined; if(first_){ G().done[k] = sc; addPts(SESSION.uid, sc*2 + (sc===q.qs.length?5:0)); log('Game','Quiz '+q.title+' '+sc+'/'+q.qs.length); } saveDB(); closeModal();
  modal({title:'Your result',body:`<h2 style="margin-bottom:10px">${sc} / ${q.qs.length}</h2>${q.qs.map((x,i)=>`<div class="small" style="margin:4px 0">${i+1}. ${esc(x[0])} <b>→ ${esc(x[1][x[2]])}</b></div>`).join('')}<p class="muted small">${first_?'Points added to the leaderboard.':'Practice attempt – points are only awarded on the first try.'}</p>`,actions:[{label:'Close',cls:'pri',act:'closeModal'}]}); render(); };
ACT.newQuiz = () => modal({title:'New quiz',size:'wide',body:`<form id="nq"><div class="field"><label>Title</label><input name="t"></div><div class="field"><label>Questions – one per line: <code>Question | Option A | Option B | Option C | correct number (1-3)</code></label><textarea name="b" style="min-height:140px"></textarea></div><div id="nqe" class="err"></div></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Create',cls:'pri',act:'saveQuiz'}]});
ACT.saveQuiz = () => { const f = $('#nq'), er = $('#nqe'); const qs = f.b.value.split('\n').map(l=>l.split('|').map(s=>s.trim())).filter(a=>a.length===5 && [1,2,3].includes(+a[4]) && a.slice(0,4).every(Boolean)).map(a=>[a[0],a.slice(1,4),+a[4]-1]); if(f.t.value.trim().length<3 || !qs.length){ er.textContent='Enter a title and at least one correctly formatted question.'; er.classList.add('show'); return; } G().extra.push({id:uid('q'),title:f.t.value.trim(),qs}); saveDB(); closeModal(); render(); };
ACT.newRaffle = () => modal({title:'New raffle',body:`<form id="rf2"><div class="fgrid"><div class="field full"><label>Raffle title</label><input name="t"></div><div class="field"><label>Prize</label><input name="p"></div><div class="field"><label>Closes</label><input type="date" name="d" min="${D.todayIso()}"></div></div><div id="rfe" class="err"></div></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Create',cls:'pri',act:'saveRaffle'}]});
ACT.saveRaffle = () => { const f = $('#rf2'), er = $('#rfe'); if(f.t.value.trim().length<3 || !f.p.value.trim() || !f.d.value){ er.textContent='Title, prize and closing date are required.'; er.classList.add('show'); return; } G().raffles.unshift({id:uid('rf'),title:f.t.value.trim(),prize:f.p.value.trim(),closes:f.d.value,entrants:[],winner:null}); log('Raffle created',f.t.value); saveDB(); closeModal(); render(); };
ACT.raffleIn = el => { const r = G().raffles.find(x=>x.id===el.dataset.id); if(!r.entrants.includes(SESSION.uid)) r.entrants.push(SESSION.uid); saveDB(); toast('You are in the draw!','ok'); render(); };
ACT.raffleDraw = el => confirmBox('Draw the winner now? This cannot be undone.', () => { const r = G().raffles.find(x=>x.id===el.dataset.id); r.winner = r.entrants[rnd(r.entrants.length)]; r.drawn = nowStamp(); notify(r.winner, `You won the raffle “${r.title}”! Prize: ${r.prize}.`, 'games'); log('Raffle drawn', `${r.title}: ${empName(r.winner)} from ${r.entrants.length} entries`); saveDB(); render(); }, 'Draw');
const MEMS = ['🍎','🚚','📦','⭐','🏆','🌱'];
ACT.memStart = () => { const cards = MEMS.concat(MEMS).map((s,i)=>({s,i,sort:rnd(1000)})).sort((a,b)=>a.sort-b.sort).map((c,k)=>({id:k,s:c.s,up:false,done:false})); window.__m = {cards,moves:0,sel:[],lock:false}; modal({title:'Memory match',body:`<div id="memb"></div>`,actions:[{label:'Close',act:'closeModal'}]}); memDraw(); };
function memDraw(){ const m = window.__m; $('#memb').innerHTML = `<p class="muted small">Moves: <b>${m.moves}</b></p><div class="memg">${m.cards.map(c=>`<button class="memc ${c.up?'up':''} ${c.done?'done':''}" data-act="memFlip" data-i="${c.id}" aria-label="card">${c.up||c.done?c.s:'?'}</button>`).join('')}</div>`; }
ACT.memFlip = el => { const m = window.__m, c = m.cards[+el.dataset.i]; if(m.lock||c.up||c.done) return; c.up = true; m.sel.push(c); memDraw();
  if(m.sel.length===2){ m.moves++; m.lock = true; const [a,b] = m.sel; setTimeout(()=>{ if(a.s===b.s){ a.done = b.done = true; } a.up = b.up = false; m.sel = []; m.lock = false; if(!$('#memb')) return; memDraw();
    if(m.cards.every(x=>x.done)){ const k = SESSION.uid+'|'+D.todayIso(), g = G(); let pts = 0; if(!g.memory[k]){ g.memory[k] = 1; pts = m.moves<=14?10:5; addPts(SESSION.uid,pts); log('Game','Memory match in '+m.moves+' moves'); saveDB(); } $('#memb').insertAdjacentHTML('beforeend',`<div class="banner" style="margin-top:12px;background:var(--ok-l);border-color:#9bd9ab;color:#14532d">Finished in ${m.moves} moves. ${pts?`+${pts} points!`:'Points are awarded once a day.'}</div>`); render(); } }, 700); } };

/* ================= SOCIAL CHANNELS (HR-050) ================= */
const SOC = () => ens('social', {channels:[{k:'TikTok',handle:'',url:''},{k:'Facebook',handle:'',url:''},{k:'Instagram',handle:'',url:''}], posts:[
  {id:'sp1',ch:'Facebook',caption:'Sample post – our teams at work (replace with real content).',link:'',status:'Approved',by:'e1',date:D.todayIso(),appr:'M Baqir'},
  {id:'sp2',ch:'Instagram',caption:'Sample post – behind the scenes in the warehouse.',link:'',status:'Approved',by:'e1',date:D.todayIso(),appr:'M Baqir'}]});
VIEWS.social = () => { const s = SOC(), posts = s.posts.filter(p=>p.status==='Approved'||isHR());
  return pageHead('Company Social Channels','Company content from TikTok, Facebook and Instagram, shown in the portal after HR review.',isHR()?`<button class="btn pri" data-act="newSocial">${ico('plus')} Add post</button>`:'') +
  `<div class="banner info">${ico('help')}<span>Live feeds need each platform’s API and developer approval (production work). In this prototype, authorised staff add posts manually. <b>Posts are only visible to staff after a second person approves them</b> (human review before publication).</span></div>
  <div class="grid g3" style="margin-bottom:16px">${s.channels.map(c=>`<div class="card"><div class="row sp"><b>${c.k}</b>${c.url?badge('Linked','ok'):badge('Not linked')}</div><div class="small muted" style="margin:6px 0 10px">${esc(c.handle)||'No handle set'}</div><div class="row">${c.url?`<a class="btn sm" target="_blank" rel="noopener noreferrer" href="${esc(c.url)}">Open channel</a>`:''}${isHR()?`<button class="btn sm" data-act="editChannel" data-k="${c.k}">Configure</button>`:''}</div></div>`).join('')}</div>
  <div class="grid g2">${posts.map(p=>`<div class="card"><div class="row sp"><b>${p.ch}</b>${p.status==='Approved'?badge('Published','ok'):badge(p.status,'warn')}</div><p>${esc(p.caption)}</p><div class="small muted">${fmt(p.date)} · added by ${esc(empName(p.by))}${p.appr?' · approved by '+esc(p.appr):''}</div><div class="row sp wrap" style="margin-top:10px">${reactBar('soc-'+p.id)}${p.link?`<a class="btn sm" target="_blank" rel="noopener noreferrer" href="${esc(p.link)}">View on ${p.ch}</a>`:''}${isHR()&&p.status==='Draft'?(p.by!==SESSION.uid?`<button class="btn sm ok" data-act="socApprove" data-id="${p.id}">Approve</button><button class="btn sm bad" data-act="socReject" data-id="${p.id}">Reject</button>`:'<span class="small muted">Needs approval from another HR user</span>'):''}</div></div>`).join('')||'<div class="empty">No posts yet.</div>'}</div>`; };
ACT.editChannel = el => { const c = SOC().channels.find(x=>x.k===el.dataset.k); modal({title:'Configure '+c.k,body:`<form id="chf"><div class="field"><label>Handle</label><input name="h" value="${esc(c.handle)}"></div><div class="field"><label>Channel URL (https)</label><input name="u" value="${esc(c.url)}" placeholder="https://"></div></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Save',cls:'pri',act:'saveChannel',data:`data-k="${c.k}"`}]}); };
ACT.saveChannel = el => { const f = $('#chf'), u = f.u.value.trim(); if(u && !/^https:\/\//.test(u)) return toast('URL must start with https://','bad'); const c = SOC().channels.find(x=>x.k===el.dataset.k); c.handle = f.h.value.trim(); c.url = u; log('Social channel configured',c.k); saveDB(); closeModal(); render(); };
ACT.newSocial = () => modal({title:'Add social post',body:`<form id="spf"><div class="fgrid"><div class="field"><label>Channel</label><select name="c">${SOC().channels.map(c=>`<option>${c.k}</option>`).join('')}</select></div><div class="field"><label>Link to post (https, optional)</label><input name="l"></div><div class="field full"><label>Caption</label><textarea name="t" maxlength="500"></textarea></div></div><p class="small muted">The post stays as a draft until another HR user approves it.</p></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Save draft',cls:'pri',act:'saveSocial'}]});
ACT.saveSocial = () => { const f = $('#spf'), l = f.l.value.trim(); if(f.t.value.trim().length<5) return toast('Enter a caption.','bad'); if(l && !/^https:\/\//.test(l)) return toast('Link must start with https://','bad'); SOC().posts.unshift({id:uid('sp'),ch:f.c.value,caption:f.t.value.trim(),link:l,status:'Draft',by:SESSION.uid,date:D.todayIso()}); log('Social post drafted',f.c.value); saveDB(); closeModal(); render(); };
ACT.socApprove = el => { const p = SOC().posts.find(x=>x.id===el.dataset.id); p.status='Approved'; p.appr = me().name; log('Social post approved',p.ch); saveDB(); render(); };
ACT.socReject = el => { const p = SOC().posts.find(x=>x.id===el.dataset.id); p.status='Rejected'; log('Social post rejected',p.ch); saveDB(); render(); };

/* ================= VIDEO PORTAL (HR-047, HR-025, HR-043) ================= */
VIEWS.stream = () => { const cat = ST.f.vcat||'', q = (ST.f.vq||'').toLowerCase(), cats = [...new Set(DB.videos.map(v=>v.cat))];
  const list = DB.videos.filter(v=>(!cat||v.cat===cat) && (!q||v.title.toLowerCase().includes(q))), feat = DB.videos[DB.videos.length-1];
  return pageHead('Video Portal','Company, induction and training videos – with views, likes and comments (Microsoft Stream-style).',isHR()?`<button class="btn" data-act="remindVideos">${ico('bell')} Remind non-viewers</button><button class="btn pri" data-act="addVideo">${ico('up')} Add video</button>`:'') +
  `<div class="toolbar"><input type="search" class="search" placeholder="Search videos" value="${esc(ST.f.vq||'')}" data-inp="vq" id="vq"><button class="bchip ${!cat?'on':''}" data-act="vcat" data-c="">All</button>${cats.map(c=>`<button class="bchip ${cat===c?'on':''}" data-act="vcat" data-c="${esc(c)}">${esc(c)}</button>`).join('')}</div>
  ${feat&&!cat&&!q?`<div class="card" style="margin-bottom:16px;display:flex;gap:18px;align-items:center;background:linear-gradient(135deg,var(--navy),var(--navy2));color:#fff;cursor:pointer" data-act="watch" data-id="${feat.id}"><div style="width:220px;aspect-ratio:16/9;border-radius:12px;background:rgba(255,255,255,.15);display:flex;align-items:center;justify-content:center">${ico('video')}</div><div><span class="badge" style="background:var(--green);color:#fff">Featured</span><h2 style="margin:8px 0 4px">${esc(feat.title)}</h2><div class="small" style="opacity:.85">${esc(feat.cat)} · ${feat.len}</div></div></div>`:''}
  <div class="grid g3">${list.map(v=>`<div class="card"><div style="aspect-ratio:16/9;background:linear-gradient(135deg,var(--navy3),var(--navy2));border-radius:10px;display:flex;align-items:center;justify-content:center;color:#fff;margin-bottom:10px;cursor:pointer" data-act="watch" data-id="${v.id}">${ico('video')}</div><b>${esc(v.title)}</b><div class="small muted">${esc(v.cat)} · ${v.len} · ${Object.keys(v.seen).length} views · ${(v.comments||[]).length} comments</div><div class="row sp" style="margin-top:8px">${v.seen[SESSION.uid]?badge('Watched','ok'):badge('New','warn')}${reactBar('vid-'+v.id)}</div></div>`).join('')||'<div class="empty">No videos found.</div>'}</div>`; };
CHG.vq = el => { ST.f.vq = el.value; render(); const f = $('#vq'); f.focus(); f.setSelectionRange(f.value.length,f.value.length); };
ACT.vcat = el => { ST.f.vcat = el.dataset.c; render(); };
ACT.watch = el => { const v = DB.videos.find(x=>x.id===el.dataset.id); v.seen[SESSION.uid] = D.todayIso(); v.comments ||= []; saveDB();
  const player = v.src.startsWith('data:video') ? `<video controls autoplay style="width:100%;border-radius:10px" src="${v.src}"></video>` : v.src ? `<a class="btn pri" target="_blank" rel="noopener noreferrer" href="${esc(v.src)}">Open video in new tab</a>` : `<div class="empty" style="background:#eef3f2;border-radius:10px">Sample entry – no media attached yet.</div>`;
  modal({title:esc(v.title),size:'wide',body:`${player}<div class="row sp" style="margin:12px 0"><span class="muted small">${esc(v.cat)} · ${v.len}</span>${reactBar('vid-'+v.id)}</div><h4>Comments</h4><div id="vcm">${v.comments.map(c=>`<div class="li"><div class="grow"><b>${esc(c.w)}</b> <span class="small muted">${fmt(c.t)}</span><div>${esc(c.m)}</div></div></div>`).join('')||'<div class="muted small">Be the first to comment.</div>'}</div><div class="row" style="margin-top:10px"><input id="vc" maxlength="300" placeholder="Add a comment"><button class="btn pri" data-act="vComment" data-id="${v.id}">Post</button></div>`,actions:[{label:'Close',act:'closeModal'}]}); };
ACT.vComment = el => { const v = DB.videos.find(x=>x.id===el.dataset.id), m = $('#vc').value.trim(); if(!m) return; v.comments.push({w:me().name,t:D.todayIso(),m}); saveDB(); ACT.watch(el); };

/* ================= EMAIL & AUTOMATION (HR-031/032/033/039/041/043) ================= */
const AUTOCFG = () => ens('autoCfg', {bday:1,colleague:1,anniv:1,videos:1,rtw:1});
function sendMail(to, subject, body, kind, extra){ const key = [kind,to,subject].join('|')+D.todayIso(); const keys = ens('autoKeys',{}); if(keys[key]) return 0; keys[key] = 1;
  ens('outbox',[]).unshift({id:uid('m'),t:nowStamp(),to,subject,body,kind,extra}); notify(to, subject, 'dashboard'); return 1; }
function runAutomation(){
  const today = D.todayIso(), cfg = AUTOCFG(); let n = 0; const md = today.slice(5);
  DB.emps.filter(e=>e.status==='active').forEach(e => {
    if(e.dob.slice(5)===md && cfg.bday) n += sendMail(e.id, `Happy birthday, ${first(e.name)}!`, `Dear ${first(e.name)},\n\nWishing you a very happy birthday from everyone at PFG Group.\n\nGlobal HR Services`, 'HR birthday email');
    if(e.dob.slice(5)===md && cfg.colleague) DB.emps.filter(c=>c.status==='active' && c.id!==e.id && c.depts.some(d=>e.depts.includes(d))).forEach(c => { n += sendMail(c.id, `It’s ${e.name}’s birthday today`, `Hi ${first(c.name)},\n\nIt’s ${e.name}’s birthday today. Click the button below to send your wishes through the HR portal.`, 'Colleague birthday', {wish:e.id,k:'bday',date:today}); });
    const yrs = +today.slice(0,4) - +e.start.slice(0,4);
    if(e.start.slice(5)===md && yrs>0 && cfg.anniv) { n += sendMail(e.id, `Happy work anniversary – ${yrs} year${yrs>1?'s':''} at PFG!`, `Dear ${first(e.name)},\n\nThank you for ${yrs} year${yrs>1?'s':''} with PFG Group.\n\nGlobal HR Services`, 'Work anniversary'); }
  });
  if(new Date().getDay()===1 && cfg.videos) DB.emps.filter(e=>e.status==='active').forEach(e => { const un = DB.videos.filter(v=>!v.seen[e.id]); if(un.length) n += sendMail(e.id, 'Weekly reminder: training videos to watch', `Hi ${first(e.name)},\n\nPlease watch: ${un.map(v=>v.title).join(', ')}.\n\nOpen the Video Portal in the HR portal.`, 'Training reminder'); });
  if(cfg.rtw) DB.rtw.filter(r=>r.status==='Due' && r.due<=today).forEach(r => managersOf(emp(r.emp)).forEach(m => { n += sendMail(m, `Return-to-work form due: ${empName(r.emp)}`, `The return-to-work form for ${empName(r.emp)} was due on ${fmt(r.due)}. Please complete it in the HR portal.`, 'RTW reminder'); }));
  DB.lastAuto = today; saveDB(); return n;
}
