function ensPos(){ if(DB.jds) return; const off = n => D.iso(D.add(D.today(),n));
  const titles = [...new Set(DB.emps.map(e=>e.title))];
  DB.jds = titles.map((t,i)=>({id:'JD'+(i+1),title:t,versions:[{v:'1.0',date:'2025-01-06',approver:'Karl Russell',eff:'2025-01-06',tags:[],comps:['Customer focus','Communication','Planning'],summary:'Sample job description – replace with the approved JD.'}]}));
  const jd = t => (DB.jds.find(j=>j.title===t)||DB.jds[0]).id;
  DB.positions = DB.emps.filter(e=>e.status==='active').map((e,i)=>({id:'POS-'+(100+i),title:e.title,jd:jd(e.title),grade:e.grade,fte:e.fte,dept:e.depts[0],region:e.region,site:e.region==='UK'?'UK site':'PK site',cc:'CC-'+e.depts[0].replace(/\W/g,'').slice(0,4).toUpperCase(),emp:e.id,since:e.start,req:''}));
  [['Warehouse Operative','Warehouse','UK','RQ-1001',-30],['Warehouse Operative','Warehouse','UK','RQ-1001',-30],['Marketing Executive','Marketing','UK','RQ-1002',-45],['BI Analyst','BI / Data','PK','RQ-1003',-12]].forEach(([t,d,r,q,s],i)=>DB.positions.push({id:'POS-9'+(10+i),title:t,jd:jd(t),grade:'G3',fte:1,dept:d,region:r,site:r+' site',cc:'CC-'+d.replace(/\W/g,'').slice(0,4).toUpperCase(),emp:null,since:off(s),req:q}));
  saveDB(); }
