ACT.saveJD = () => { const f = $('#jf2'), er = $('#jfe2'); if(f.t.value.trim().length<3 || f.s.value.trim().length<10 || !/^\d+(\.\d+)*$/.test(f.v.value.trim())){ er.textContent='Title, summary (10+ chars) and numeric version are required.'; er.classList.add('show'); return; }
  const ver = {v:f.v.value.trim(),date:D.todayIso(),approver:f.a.value.trim(),eff:f.e.value,tags:f.g.value.split(',').map(s=>s.trim()).filter(Boolean),comps:f.c.value.split(',').map(s=>s.trim()).filter(Boolean),summary:f.s.value.trim()};
  let j = DB.jds.find(x=>x.title.toLowerCase()===f.t.value.trim().toLowerCase()); if(j) j.versions.unshift(ver); else DB.jds.push({id:'JD'+(DB.jds.length+1),title:f.t.value.trim(),versions:[ver]}); log('JD published',f.t.value+' v'+ver.v); saveDB(); closeModal(); render(); };

/* ================= ATTENDANCE CROSS-CHECK (BRS 5.6, HR-011) ================= */
const SH_T = {E:['06:00','14:00'],D:['09:00','17:30'],L:['14:00','22:00']};
function shiftFor(e, d){ const lv = DB.leave.find(l=>l.emp===e.id&&l.status==='approved'&&d>=l.start&&d<=l.end&&!['WFH','HALF'].includes(l.type)); if(lv) return 'LV'; if(phName(d,e.region)) return 'PH'; const wk = D.iso(mondayOf(D.parse(d)));
  for(const dep of e.depts){ const R = DB.rota[dep+'|'+wk]; const c = R && R[e.id] && R[e.id][d]; if(c) return c; } return isRest(e,d)?'OFF':'D'; }
function genPunches(){ const P = ens('punches',[]); const today = D.today(); let n = 0;
  DB.emps.filter(e=>e.status==='active').forEach((e,ei) => { for(let k=7;k>=1;k--){ const d = D.iso(D.add(today,-k)); if(P.some(p=>p.emp===e.id&&p.date===d)) continue; const h = (ei*31+k*17+ +e.id.slice(1)*7)%100, sh = shiftFor(e,d);
    if(['LV','PH','OFF','N'].includes(sh)){ if(h%41===0 && sh!=='N'){ P.push({emp:e.id,date:d,in:'09:00',out:'13:00'}); n++; } continue; }
    const [s,en] = SH_T[sh]; if(h%23===0) continue; const p = {emp:e.id,date:d,in:fmtHM(hm(s)+(h%7)-3),out:fmtHM(hm(en)+(h%9)-2)};
    if(h%19===0) p.in = fmtHM(hm(s)+25+h%15); if(h%29===0) p.out = ''; if(h%37===0) p.out = fmtHM(hm(en)+240); P.push(p); n++; } }); return n; }
const GRACE = 10, MAXH = 10;
function crossCheck(){ const A = ens('anoms',[]); let added = 0; const today = D.todayIso();
  DB.emps.filter(e=>e.status==='active').forEach(e => { for(let k=7;k>=1;k--){ const d = D.iso(D.add(D.today(),-k)), sh = shiftFor(e,d), p = (DB.punches||[]).find(x=>x.emp===e.id&&x.date===d), found = [];
    if(['E','D','L'].includes(sh)){ const [s,en] = SH_T[sh];
      if(!p) found.push(['No-show','No clocking against a rostered '+sh+' shift']);
      else if(!p.in || !p.out) found.push(['Missing punch', p.in?'No clock-out':'No clock-in']);
      else { if(hm(p.in) > hm(s)+GRACE) found.push(['Late arrival',`Clocked in ${p.in}, shift starts ${s}`]); if(hm(p.out) < hm(en)-GRACE) found.push(['Early departure',`Clocked out ${p.out}, shift ends ${en}`]); if((hm(p.out)-hm(p.in))/60 > MAXH) found.push(['Overtime breach',`${((hm(p.out)-hm(p.in))/60).toFixed(1)} h on site`]); } }
    else if(p && sh!=='N') found.push(['Unauthorised attendance',`Clocked ${p.in}–${p.out||'?'} on ${sh==='LV'?'approved leave':sh==='PH'?'a public holiday':'a rest day'}`]);
    found.forEach(([type,detail]) => { const key = e.id+'|'+d+'|'+type; if(!A.some(a=>a.key===key)){ A.push({id:uid('an'),key,emp:e.id,date:d,type,detail,cat:'',status:'Open',due:D.iso(D.add(D.parse(d),3)),log:[]}); added++; } }); } });
  A.forEach(a => { if(a.status==='Open' && a.due<today){ a.status='Escalated to AM'; a.log.push({t:nowStamp(),w:'Auto-escalated – manager SLA breached'}); } }); saveDB(); return added; }
const ROOT = ['Forgot to clock','Card / reader fault','Approved swap','Late transport','Sickness','Authorised overtime','Unauthorised – disciplinary review','Data error'];
VIEWS.attendance = () => { const A = ens('anoms',[]), f = ST.f.an ||= {st:'',dept:''}, vis = isHR() ? DB.emps : manageable(); const list = A.filter(a=>vis.some(e=>e.id===a.emp) && (!f.st||a.status===f.st) && (!f.dept||emp(a.emp).depts.includes(f.dept))).sort((a,b)=>b.date.localeCompare(a.date));
  const byType = {}, byDept = {}; list.filter(a=>a.status!=='Resolved').forEach(a=>{ byType[a.type]=(byType[a.type]||0)+1; const d = emp(a.emp).depts[0]; byDept[d]=(byDept[d]||0)+1; });
  return pageHead('Attendance Cross-check','Rota vs clocking (Paxton) with an anomaly queue, manager triage and AM escalation.',`<button class="btn" data-act="anImport">${ico('up')} Import punches (CSV)</button><button class="btn" data-act="anSample">Load sample Paxton data</button><button class="btn pri" data-act="anRun">${ico('act')} Run cross-check</button>`) +
  `<div class="banner info">${ico('help')}<span>Rules (ASSUMPTIONS to confirm): ${GRACE}-minute grace, ${MAXH}-hour overtime flag, manager SLA 3 days then auto-escalation to Attendance Management. Night shifts are not checked yet. Live Paxton ingestion (daily / near-real-time) is a Phase 3 integration. Clustering below is simple grouping, not machine learning.</span></div>
  <div class="grid g3" style="margin-bottom:16px"><div class="card"><h3>Open anomalies by type</h3>${Object.entries(byType).map(([t,n])=>`<div class="hbar"><span>${t}</span><div class="prog o"><i style="width:${n/Math.max(...Object.values(byType))*100}%"></i></div><b>${n}</b></div>`).join('')||'<span class="muted">None</span>'}</div><div class="card"><h3>Hot-spots by department</h3>${Object.entries(byDept).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([t,n])=>`<div class="hbar"><span>${esc(t)}</span><div class="prog r"><i style="width:${n/Math.max(...Object.values(byDept))*100}%"></i></div><b>${n}</b></div>`).join('')||'<span class="muted">None</span>'}</div><div class="card kpi"><span class="t">Queue</span><span class="v">${list.filter(a=>a.status!=='Resolved').length}</span><span class="s muted">${list.filter(a=>a.status==='Escalated to AM').length} escalated to Attendance Management</span></div></div>
  <div class="toolbar"><select data-chg="anF" data-k="st"><option value="">All statuses</option>${['Open','Triaged','Escalated to AM','Resolved'].map(s=>`<option ${f.st===s?'selected':''}>${s}</option>`).join('')}</select><select data-chg="anF" data-k="dept"><option value="">All departments</option>${deptOptions(f.dept)}</select><span class="grow"></span><button class="btn sm" data-act="anBulk" data-s="Resolved">Resolve selected</button><button class="btn sm" data-act="anBulk" data-s="Escalated to AM">Escalate selected</button><button class="btn pri sm" data-act="anPublish">Publish validated hours to payroll prep</button></div>` +
  table([{h:'<input type="checkbox" style="width:auto" data-chg="anAll">',f:a=>`<input type="checkbox" style="width:auto" class="anc" value="${a.id}">`},{h:'Date',f:a=>fmt(a.date)},{h:'Employee',f:a=>esc(empName(a.emp))},{h:'Anomaly',f:a=>`<b>${a.type}</b><div class="small muted">${esc(a.detail)}</div>`},{h:'Root cause',f:a=>`<select data-chg="anCause" data-id="${a.id}" style="width:auto;padding:5px"><option value="">— choose —</option>${ROOT.map(r=>`<option ${a.cat===r?'selected':''}>${r}</option>`).join('')}</select>`},{h:'Due',f:a=>fmtS(a.due)},{h:'Status',f:a=>statusBadge(a.status)}], list, {empty:'No anomalies. Load sample data, then run the cross-check.'}); };
CHG.anF = el => { ST.f.an[el.dataset.k] = el.value; render(); };
CHG.anAll = el => $$('.anc').forEach(c=>c.checked = el.checked);
CHG.anCause = el => { const a = DB.anoms.find(x=>x.id===el.dataset.id); a.cat = el.value; if(a.status==='Open'&&el.value) a.status='Triaged'; a.log.push({t:nowStamp(),w:'Root cause: '+el.value+' ('+me().name+')'}); saveDB(); render(); };
ACT.anSample = () => { const n = genPunches(); toast(`${n} sample punches loaded`,'ok'); ACT.anRun(); };
ACT.anRun = () => { const n = crossCheck(); log('Attendance cross-check', n+' new anomalies'); toast(n?`${n} new anomalies found`:'No new anomalies','ok'); render(); };
ACT.anBulk = el => { const ids = $$('.anc:checked').map(c=>c.value); if(!ids.length) return toast('Select at least one row.','bad'); let n = 0, skip = 0; ids.forEach(id => { const a = DB.anoms.find(x=>x.id===id); if(el.dataset.s==='Resolved' && !a.cat){ skip++; return; } a.status = el.dataset.s; a.log.push({t:nowStamp(),w:el.dataset.s+' by '+me().name}); n++; }); saveDB(); toast(`${n} updated${skip?`, ${skip} skipped (choose a root cause first)`:''}`, skip?'':'ok'); render(); };
ACT.anPublish = () => { const P = DB.punches||[], H = ens('payHours',{}); let n = 0; P.forEach(p => { if(!p.in||!p.out) return; const bad = DB.anoms.some(a=>a.emp===p.emp&&a.date===p.date&&a.status!=='Resolved'); if(bad) return; H[p.emp+'|'+p.date] = +((hm(p.out)-hm(p.in))/60).toFixed(2); n++; }); log('Hours published to payroll prep', n+' days'); saveDB(); toast(`${n} validated day(s) published`,'ok'); };
ACT.anImport = () => modal({title:'Import punches',body:`<p class="small muted">CSV with header <code>employee_email,date,in,out</code> (24-hour times, blank out = missing).</p><input type="file" accept=".csv" data-chg="punchCSV">`,actions:[{label:'Close',act:'closeModal'}]});
CHG.punchCSV = el => { const f = el.files[0]; if(!f) return; const r = new FileReader(); r.onload = () => { const P = ens('punches',[]); let n = 0, bad = 0; r.result.replace(/^﻿/,'').split(/\r?\n/).filter(Boolean).slice(1).forEach(l => { const [em,d,i,o] = l.split(',').map(s=>s.trim()); const e = DB.emps.find(x=>x.email.toLowerCase()===(em||'').toLowerCase()); if(!e||!/^\d{4}-\d{2}-\d{2}$/.test(d||'')||(i&&!/^\d{2}:\d{2}$/.test(i))||(o&&!/^\d{2}:\d{2}$/.test(o))){ bad++; return; } if(!P.some(p=>p.emp===e.id&&p.date===d)){ P.push({emp:e.id,date:d,in:i||'',out:o||''}); n++; } }); saveDB(); closeModal(); toast(`${n} imported${bad?`, ${bad} rejected`:''}`, bad?'':'ok'); ACT.anRun(); }; r.readAsText(f); };

/* ================= PAYROLL PREPARATION (BRS 5.11) ================= */
const PAYCFG = () => ens('payCfg', {niRate:15, niThreshold:5000, pensionRate:3, nomWages:'TBC-WAGES', nomNI:'TBC-ERNI', nomPension:'TBC-ERPEN', nomControl:'TBC-PAYCTRL'});
function payRows(month){ const [y,m] = month.split('-').map(Number), last = new Date(y,m,0,12).getDate(); const days = Array.from({length:last},(_,i)=>`${month}-${String(i+1).padStart(2,'0')}`); const H = DB.payHours||{};
  return DB.emps.filter(e=>e.status==='active' || (e.leaveDate||'').startsWith(month)).map(e => { const work = days.filter(d=>!isWeekend(d) && !phName(d,e.region) && d>=e.start && (!e.leaveDate||d<=e.leaveDate)); let hol=0, ssp=0, unpaid=0, other=0;
    DB.leave.filter(l=>l.emp===e.id && l.status==='approved').forEach(l => work.forEach(d => { const v = dayValue(l,d,e.region); if(!v) return; if(l.type==='HOL') hol+=v; else if(['SICK_SSP','SICK'].includes(l.type)) ssp+=v; else if(['UNAUTH','LATE'].includes(l.type)) unpaid+=v; else if(!['WFH','HALF'].includes(l.type)) other+=v; }));
    const pubH = days.reduce((s,d)=>s+(H[e.id+'|'+d]||0),0), ded = DB.deductions.filter(x=>x.emp===e.id&&x.status.startsWith('Approved')&&x.date.startsWith(month)).reduce((s,x)=>s+x.amount,0);
    const ex = []; if(DB.leave.some(l=>l.emp===e.id&&l.status==='pending'&&l.start.startsWith(month))) ex.push('Pending leave in period'); if((DB.anoms||[]).some(a=>a.emp===e.id&&a.date.startsWith(month)&&a.status!=='Resolved')) ex.push('Open attendance anomaly'); if(DB.deductions.some(x=>x.emp===e.id&&x.date.startsWith(month)&&!x.ack&&x.status.startsWith('Approved'))) ex.push('Deduction not acknowledged'); if(!e.salary) ex.push('No salary on file');
    return {e, work:work.length, hol, ssp, unpaid, other, paid:work.length-unpaid, pubH, ded, ex}; }); }
VIEWS.payroll = () => { const month = ST.f.pm || D.todayIso().slice(0,7), pm = D.iso(new Date(+month.slice(0,4), +month.slice(5,7)-2, 1, 12)).slice(0,7), rows = payRows(month), prev = payRows(pm), cfg = PAYCFG(), k = tabOf('pay','val');
  const tot = rs => rs.reduce((s,r)=>s+r.paid,0), exc = rows.filter(r=>r.ex.length);
  const monthly = r => (r.e.salary||0)/12 * (r.work? r.paid/r.work : 1);
  let body = '';
  if(k==='val') body = `<div class="grid g4" style="margin-bottom:16px">${[['Employees',rows.length],['Paid working days',tot(rows)],['Prior period',tot(prev)],['Exceptions',exc.length]].map(([t,v])=>`<div class="card kpi"><span class="t">${t}</span><span class="v">${v}</span></div>`).join('')}</div><div class="banner info">${ico('help')}<span>Variance vs ${pm}: <b>${tot(prev)?((tot(rows)-tot(prev))/tot(prev)*100).toFixed(2):'0.00'}%</b> paid days. Phase 1 prepares validated inputs only – payroll itself is processed externally.</span></div>` + table([{h:'Employee',f:r=>esc(r.e.name)},{h:'Working days',f:r=>r.work},{h:'Holiday',f:r=>num1(r.hol)},{h:'Sick',f:r=>num1(r.ssp)},{h:'Unpaid',f:r=>num1(r.unpaid)},{h:'Paid days',f:r=>num1(r.paid)},{h:'Clocked hrs (published)',f:r=>r.pubH?r.pubH.toFixed(2):'—'},{h:'Deductions',cls:'right',f:r=>r.ded?gbp(r.ded):'—'},{h:'Exceptions',f:r=>r.ex.map(x=>badge(x,'warn')).join(' ')||badge('Clean','ok')}], rows);
  if(k==='jrn'){ const byDept = {}; rows.forEach(r => { const d = r.e.depts[0]; const g = monthly(r), ni = Math.max(0, g - cfg.niThreshold/12) * cfg.niRate/100, pen = g*cfg.pensionRate/100; const o = byDept[d] ||= {g:0,ni:0,pen:0}; o.g += g; o.ni += ni; o.pen += pen; });
    const lines = []; Object.entries(byDept).forEach(([d,o]) => { lines.push([cfg.nomWages,'Gross wages',o.g,0,d]); lines.push([cfg.nomNI,'Employer NI',o.ni,0,d]); lines.push([cfg.nomPension,'Employer pension',o.pen,0,d]); }); const tdr = lines.reduce((s,l)=>s+l[2],0); lines.push([cfg.nomControl,'Payroll control (liability)',0,tdr,'']); window.__jrn = lines;
    body = `<div class="banner">${ico('warn')}<span><b>ASSUMPTIONS – Finance to confirm:</b> employer NI ${cfg.niRate}% above £${cfg.niThreshold} a year, employer pension ${cfg.pensionRate}%, placeholder nominal codes. Salaries below are sample inputs. VAT is not applicable to payroll journals. Currency GBP.</span></div>
    <div class="card" style="margin-bottom:16px"><h3>Salary inputs (annual, £)</h3><div class="grid g4">${rows.filter(r=>r.e.region==='UK').map(r=>`<div class="field"><label>${esc(r.e.name)}</label><input type="number" min="0" step="100" value="${r.e.salary||''}" data-chg="salary" data-id="${r.e.id}"></div>`).join('')}</div><p class="small muted">PK payroll runs in PKR and is exported separately (not in this GBP journal).</p></div>` +
    table([{h:'Nominal',f:l=>esc(l[0])},{h:'Narration',f:l=>esc(l[1])},{h:'Department tracking',f:l=>esc(l[4])||'—'},{h:'Debit',cls:'right',f:l=>l[2]?gbp(l[2]):''},{h:'Credit',cls:'right',f:l=>l[3]?gbp(l[3]):''}], lines) + `<div class="row sp" style="margin-top:12px"><span>${Math.abs(lines.reduce((s,l)=>s+l[2]-l[3],0))<0.005?badge('Journal balances','ok'):badge('Journal out of balance','bad')}</span><button class="btn pri" data-act="jrnExport">${ico('down')} Export journal CSV (Xero / Paycircle import)</button></div>`; }
  if(k==='cfg') body = `<div class="card"><form id="pcf"><div class="fgrid">${[['niRate','Employer NI rate %'],['niThreshold','Employer NI threshold (£ per year)'],['pensionRate','Employer pension %'],['nomWages','Wages nominal code'],['nomNI','Employer NI nominal (single)'],['nomPension','Employer pension nominal (single)'],['nomControl','Payroll control nominal']].map(([k,l])=>`<div class="field"><label>${l}</label><input name="${k}" value="${esc(cfg[k])}"></div>`).join('')}</div><button class="btn pri" data-act="savePay">Save</button></form></div>`;
  return pageHead('Payroll Preparation','Pre-payroll validation pack, period reconciliation and finance journal.',`<input type="month" value="${month}" data-chg="payMonth" style="width:170px">`) + tabsHtml('pay',[['val','Validation pack'],['jrn','Finance journal'],['cfg','Rates & nominals']],'val') + body; };
CHG.payMonth = el => { if(el.value){ ST.f.pm = el.value; render(); } };
CHG.salary = el => { const e = emp(el.dataset.id), v = +el.value; if(v<0||isNaN(v)) return; e.salary = v||0; saveDB(); render(); };
ACT.savePay = () => { const f = $('#pcf'), c = PAYCFG(); ['niRate','niThreshold','pensionRate'].forEach(k=>{ const v = +f[k].value; if(!(v>=0)) return; c[k] = v; }); ['nomWages','nomNI','nomPension','nomControl'].forEach(k=>c[k] = f[k].value.trim()||c[k]); log('Payroll rates changed',''); saveDB(); toast('Saved','ok'); render(); };
ACT.jrnExport = () => { const m = ST.f.pm || D.todayIso().slice(0,7); csvDownload('payroll_journal_'+m, ['Date','Narration','Account code','Debit','Credit','Tracking category (Department)'], window.__jrn.map(l=>[m+'-28','Payroll '+m+' – '+l[1],l[0],l[2]?l[2].toFixed(2):'',l[3]?l[3].toFixed(2):'',l[4]])); };

/* ================= AI COPILOT & FORECASTS (BRS section 6) ================= */
const personIn = (q, list) => list.find(e => e.name.toLowerCase().split(' ').filter(w=>w.length>2).every(w=>q.includes(w))) || list.find(e => q.includes(e.name.toLowerCase().split(' ')[0]) && e.name.split(' ')[0].length>3);
function copilot(qRaw){
  const q = qRaw.toLowerCase(), u = me(), today = D.todayIso(), src = [], vis = isHR() ? DB.emps : visibleEmps({leavers:false}); let a = '';
  const who = personIn(q, vis);
  if(/who.*(off|away|absent|on leave|holiday)/.test(q) || /off today|absent today/.test(q)){ const tom = /tomorrow/.test(q), d = tom ? D.iso(D.add(D.today(),1)) : today; const l = absentToday(d).filter(x=>vis.some(e=>e.id===x.emp)); a = l.length ? `People off ${tom?'tomorrow':'today'}: ` + l.map(x=>{ const hide = LT[x.type].sick && !isMgr(); return `${empName(x.emp)} (${hide?'absent':LEGEND_LABEL[x.type]}, back ${fmtS(nextWorkday(x.end,emp(x.emp).region))})`; }).join('; ') : 'Nobody in your view is off.'; src.push('Leave calendar'); }
  else if(/balance|how many (days|holiday)|days (left|remaining)|holiday (left|remaining)/.test(q)){ const e = who && isMgr() ? who : u; const b = balance(e, curLY(e)); a = `${e.id===u.id?'You have':e.name+' has'} ${num1(b.free)} day(s) available in ${lyLabel(e,curLY(e))} (entitlement ${num1(b.total)}, taken ${num1(b.taken)}, booked ${num1(b.upcoming)}, pending ${num1(b.pending)}).`; src.push('Leave balances'); }
  else if(/bradford/.test(q)){ if(!isMgr()) a = 'Bradford Factor scores are restricted to line managers and HR.'; else { const e = who; if(e){ const b = bradford(e.id); a = `${e.name}: ${b.spells} spell(s), ${num1(b.days)} day(s) in the last 52 weeks – Bradford Factor ${b.score} (${bradLevel(b.score)[0]}). Thresholds are placeholders until HR confirms policy.`; } else { const t = vis.map(e=>({e,b:bradford(e.id)})).filter(x=>x.b.spells).sort((a,b)=>b.b.score-a.b.score).slice(0,3); a = 'Highest Bradford scores: ' + (t.map(x=>`${x.e.name} ${x.b.score}`).join('; ')||'none') + '.'; } src.push('Bradford Factor report'); } }
  else if(/right to work|rtw|visa|expir/.test(q)){ if(!isHR()) a = 'Right-to-work records are restricted to HR.'; else { const r = DB.rtwChecks.filter(x=>x.expiry && D.diff(today,x.expiry)<=60).map(x=>`${empName(x.emp)} (${D.diff(today,x.expiry)<0?'expired':'expires '+fmtS(x.expiry)})`); a = r.length ? 'Right-to-work due within 60 days or expired: '+r.join('; ')+'.' : 'No right-to-work expiries within 60 days.'; src.push('Right to Work tracker'); } }
  else if(/headcount|how many (staff|employees|people)/.test(q)){ const dep = DB.depts.find(d=>q.includes(d.toLowerCase())); const l = vis.filter(e=>e.status==='active' && (!dep||e.depts.includes(dep))); a = `${l.length} active employee(s)${dep?' in '+dep:''} in your view (UK ${l.filter(e=>e.region==='UK').length}, PK ${l.filter(e=>e.region==='PK').length}).`; src.push('Personnel files'); }
  else if(/sick(ness)? (trend|rate)|trend/.test(q)){ if(!isMgr()) a = 'Sickness trends are restricted to managers and HR.'; else { const t = vis.reduce((s,e)=>s+bradford(e.id).days,0); a = `${num1(t)} sickness working day(s) in the last 52 weeks across ${vis.length} people in your view.`; src.push('Sickness records'); } }
  else if(/probation/.test(q)){ const p = DB.probation.filter(x=>isHR()||manageable().some(m=>m.id===x.emp)); a = p.length ? p.map(x=>`${empName(x.emp)} (started ${fmtS(x.start)})`).join('; ') : 'No probationers in your view.'; src.push('Probation tracker'); }
  else if(/requisition|vacanc/.test(q)){ const r = DB.requisitions.filter(x=>x.stage!==3&&x.stage!==4); a = r.length ? 'Open requisitions: '+r.map(x=>`${x.id} ${x.title} (${x.status})`).join('; ') : 'No open requisitions.'; src.push('Requisitions'); }
  else if(/ticket|helpdesk/.test(q)){ const t = DB.tickets.filter(x=>x.status!=='Resolved' && (isHR()||x.emp===u.id)); a = `${t.length} open ticket(s)${t.length?': '+t.map(x=>x.id+' '+x.subject).join('; '):''}.`; src.push('Helpdesk'); }
  else if(/sick pay|ssp|statutory|redundan|dismiss|maternity|paternity|tribunal|notice period|disciplin/.test(q)){ a = 'This is an employment-law question. I can only give a pointer, not legal advice: check the relevant internal policy below and GOV.UK / ACAS guidance, and speak to HR before acting. '; const ps = DB.policies.filter(p=>/sick|absence|discipl|leave/i.test(p.title)); a += ps.length ? 'Related internal policies: '+ps.map(p=>p.title+' v'+p.ver).join('; ')+'.' : ''; ps.forEach(p=>src.push('Policy: '+p.title)); }
  else { const words = q.replace(/[^a-z0-9 ]/g,' ').split(' ').filter(w=>w.length>3 && !['what','when','where','which','policy','about','does','this','that','have','with','from','tell','show','give'].includes(w)); const hits = DB.policies.map(p=>({p,s:p.body.split(/(?<=\.)\s+/).filter(s=>words.some(w=>s.toLowerCase().includes(w)))})).filter(x=>x.s.length);
    if(hits.length){ a = hits.slice(0,2).map(h=>`<b>${esc(h.p.title)}</b> (v${h.p.ver}): “${esc(h.s.slice(0,2).join(' '))}”`).join('<br><br>') + `<br><br><span class="small muted">Jurisdiction note: you are in ${u.region}; check whether a ${u.region==='UK'?'PK':'UK'} variant applies. Not legal advice.</span>`; hits.slice(0,2).forEach(h=>src.push('Policy: '+h.p.title)); return {html:a, src}; }
    a = 'I can answer questions such as: “who is off today?”, “what is my leave balance?”, “headcount in Warehouse”, “Bradford factor”, “right to work expiries”, or ask about a policy (e.g. “carry-over”). Try rephrasing, or contact HR.'; }
  return {html: a.includes('<b>')?a:esc(a), src};
}
function forecastGrid(){ const weeks = Array.from({length:8},(_,i)=>D.iso(D.add(mondayOf(D.today()),i*7))); const pool = isHR()?DB.depts:[...new Set(visibleEmps().flatMap(e=>e.depts))];
  const rows = pool.map(d => { const staff = DB.emps.filter(e=>e.status==='active'&&e.depts.includes(d)); if(!staff.length) return null; return {d, n:staff.length, cells:weeks.map(w => { let off = 0, tot = 0; for(let i=0;i<5;i++){ const day = D.iso(D.add(D.parse(w),i)); staff.forEach(e => { if(phName(day,e.region)) return; tot++; if(DB.leave.some(l=>l.emp===e.id&&['approved','pending'].includes(l.status)&&!['WFH','HALF'].includes(l.type)&&day>=l.start&&day<=l.end)) off++; }); } return tot?off/tot:0; })}; }).filter(Boolean); return {weeks, rows}; }
VIEWS.copilot = () => { const k = tabOf('ai','ask'), chat = ST.ai ||= [{b:1,html:`Hello ${esc(first(me().name))}. Ask me about leave, headcount, policies or compliance. I only use data you are allowed to see.`,src:[]}]; let body = '';
  if(k==='ask') body = `<div class="banner info">${ico('shield')}<span><b>Guardrails:</b> answers are drawn from portal data and published policies, limited to your access. Not legal advice. Every question is logged (prompt and content audit). Decisions stay with people. This prototype uses rule-based answers, not a generative model.</span></div><div class="card"><div id="aib" style="display:flex;flex-direction:column;gap:10px;min-height:260px;max-height:48vh;overflow:auto">${chat.map(m=>`<div class="ai-msg ${m.b?'ai-b':'ai-u'}">${m.b?m.html:esc(m.html)}${m.src?.length?`<div class="small muted" style="margin-top:6px">Sources: ${m.src.map(esc).join(', ')}</div>`:''}</div>`).join('')}</div><div class="row" style="margin-top:12px"><input id="aiq" maxlength="200" placeholder="Ask a question…" onkeydown="if(event.key==='Enter')ACT.aiAsk()"><button class="btn pri" data-act="aiAsk">Ask</button></div><div class="row wrap" style="margin-top:10px">${['Who is off today?','What is my leave balance?','Headcount in Warehouse','What is the carry-over rule?','Right to work expiries'].map(s=>`<button class="bchip" data-act="aiSug" data-q="${esc(s)}">${esc(s)}</button>`).join('')}</div></div>`;
  if(k==='fc'){ const f = forecastGrid(); body = `<div class="banner info">${ico('help')}<span>Leave coverage forecast: share of working days booked or requested off. Red = over 30% (an <b>assumption</b> – set per site). Based on approved and pending leave and absence only. Headcount forecast is on the Positions page.</span></div><div class="tw"><table class="t heat"><thead><tr><th>Department</th><th>Staff</th>${f.weeks.map(w=>`<th>${fmtS(w)}</th>`).join('')}</tr></thead><tbody>${f.rows.map(r=>`<tr><td style="text-align:left"><b>${esc(r.d)}</b></td><td>${r.n}</td>${r.cells.map(c=>`<td style="background:${c>.3?'#fecaca':c>.15?'#fde68a':c>0?'#d9f0dd':'#fff'}">${c?Math.round(c*100)+'%':'–'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`; }
  if(k==='aud') body = isHR() ? table([{h:'When',f:a=>fmtDT(a.t)},{h:'User',f:a=>esc(empName(a.u))},{h:'Prompt',f:a=>esc(a.q)},{h:'Sources',f:a=>esc(a.src.join(', '))||'—'}], ens('aiLog',[]), {empty:'No prompts logged yet.'}) : '<div class="banner">Prompt audit is visible to HR only.</div>';
  return pageHead('AI Copilot & Forecasts','Ask management questions, see leave-coverage gaps, and review the prompt audit.') + tabsHtml('ai',[['ask','Ask Copilot'],['fc','Coverage forecast'],['aud','Prompt audit']],'ask') + body; };
AFTER.copilot = () => { const b = $('#aib'); if(b) b.scrollTop = b.scrollHeight; };
ACT.aiAsk = () => { const i = $('#aiq'), q = i.value.trim(); if(!q) return; const chat = ST.ai ||= []; const r = copilot(q); chat.push({b:0,html:q}); chat.push({b:1,html:r.html,src:r.src}); ens('aiLog',[]).unshift({t:nowStamp(),u:SESSION.uid,q,src:r.src}); if(DB.aiLog.length>200) DB.aiLog.length = 200; saveDB(); render(); $('#aiq')?.focus(); };
ACT.aiSug = el => { render(); $('#aiq').value = el.dataset.q; ACT.aiAsk(); };

/* ================= BI / DATASET EXPORTS (BRS 5.13) ================= */
const BI = [
 ['Employees','People master data (no banking, tax or special-category fields)',()=>[['EmployeeID','Name','Title','Departments','Company','Region','Manager','Start','Leave date','Status','Contract','FTE'],DB.emps.map(e=>[e.id,e.name,e.title,e.depts.join(' / '),e.company,e.region,empName(e.mgr),e.start,e.leaveDate||'',e.status,e.contract,e.fte])]],
 ['Leave & absence','Every leave and absence record',()=>[['RecordID','EmployeeID','Type','From','To','Half','Working days','Status'],DB.leave.map(l=>[l.id,l.emp,LT[l.type].name,l.start,l.end,l.half||'',recDays(l,emp(l.emp).region),l.status])]],
 ['Leave balances','Entitlement, taken, booked and remaining for this year',()=>[['EmployeeID','Year','Entitlement','Carry-over','Taken','Booked','Pending','Remaining'],DB.emps.filter(e=>e.status==='active').map(e=>{ const y = curLY(e), b = balance(e,y); return [e.id,lyLabel(e,y),b.ent,b.carry,b.taken,b.upcoming,b.pending,b.remaining]; })]],
 ['Sickness & Bradford','Rolling 52-week spells, days and score',()=>[['EmployeeID','Spells','Days','BradfordScore'],DB.emps.filter(e=>e.status==='active').map(e=>{ const b = bradford(e.id); return [e.id,b.spells,b.days,b.score]; })]],
 ['Requisitions','Approval pipeline',()=>[['Ref','Title','Department','Region','Stage','Status','Headcount','Budget','Salary per head'],DB.requisitions.map(r=>[r.id,r.title,r.dept,r.region,r.stage,r.status,r.headcount,r.budget,r.salary])]],
 ['Attendance anomalies','Rota vs clocking exceptions',()=>[['Date','EmployeeID','Type','Root cause','Status'],(DB.anoms||[]).map(a=>[a.date,a.emp,a.type,a.cat,a.status])]],
 ['Training','Certificates and expiry',()=>[['EmployeeID','Course','Completed','Status'],DB.certs.map(c=>{ const co = DB.courses.find(x=>x.id===c.course); return [c.emp,co.name,c.date,certState(emp(c.emp),co).s]; })]],
 ['Tickets','Helpdesk volumes and SLA',()=>[['Ticket','Category','Raised','Status','Priority','SLA days'],DB.tickets.map(t=>[t.id,t.cat,t.raised,t.status,t.pri,t.sla])]]
];
const biCard = () => `<div class="banner info">${ico('help')}<span>Each export is a clean CSV that Power BI can load. A governed Power BI / Fabric dataflow with scheduled refresh is a production integration (BRS section 7). Personal data is minimised – no bank, tax or special-category fields.</span></div><div class="grid g3">${BI.map((b,i)=>`<div class="card"><b>${b[0]}</b><p class="small muted" style="margin:6px 0 12px">${b[1]}</p><button class="btn sm pri" data-act="biExp" data-i="${i}">${ico('down')} Export CSV</button></div>`).join('')}</div>`;
ACT.biExp = el => { const [h,r] = BI[+el.dataset.i][2](); csvDownload('bi_'+BI[+el.dataset.i][0].replace(/\W+/g,'_').toLowerCase(), h, r); };

